import { z } from "zod";
import { ADVERTISING_EVENT_TYPES, MOBILE_PLATFORMS } from "../enums";
import { beaconIdentifierSchema, publicIdSchema } from "./common";

/**
 * Anonymous per-install identifier generated by the mobile app (e.g. a random UUID kept in app
 * storage). The server stores only a keyed hash of it. Never send Bluetooth MAC addresses,
 * advertising IDs or other personal identifiers.
 */
export const deviceTokenSchema = z
  .string()
  .trim()
  .min(16, "Device token is too short.")
  .max(128, "Device token is too long.")
  .regex(/^[A-Za-z0-9._-]+$/, "Device token contains invalid characters.");

export const mobileCampaignQuerySchema = z.object({
  /** Campaign beacon key decoded from the advertisement (iBeacon minor or BPA campaign key). */
  key: z.coerce.number().int().min(1).max(0xffff).optional(),
  device: deviceTokenSchema.optional(),
  rssi: z.coerce.number().int().min(-127).max(20).optional(),
});
export type MobileCampaignQuery = z.infer<typeof mobileCampaignQuerySchema>;

export const mobileCampaignSchema = z.object({
  id: z.string(),
  beaconKey: z.number().int(),
  priority: z.number().int(),
  endAt: z.string().nullable(),
  notification: z.object({
    title: z.string(),
    message: z.string(),
    imageUrl: z.string().nullable(),
    description: z.string().nullable(),
    landingUrl: z.string().nullable(),
    ctaLabel: z.string().nullable(),
    /** Discard the notification if not displayed before this time. */
    expiresAt: z.string(),
  }),
  policy: z.object({
    cooldownMinutes: z.number().int(),
    maxNotificationsPerDay: z.number().int(),
  }),
  eligibility: z.object({
    /** Null when the request did not include a device token, so eligibility could not be evaluated. */
    eligible: z.boolean().nullable(),
    reason: z
      .enum(["ok", "too_far", "quiet_hours", "cooldown", "daily_limit", "campaign_limit", "not_evaluated"])
      .nullable(),
  }),
});
export type MobileCampaign = z.infer<typeof mobileCampaignSchema>;

export const mobileCampaignsResponseSchema = z.object({
  beaconId: z.string(),
  station: z.object({ name: z.string(), location: z.string().nullable() }),
  proximity: z.object({ minRssi: z.number().int() }),
  quietHours: z.object({ active: z.boolean() }),
  campaigns: z.array(mobileCampaignSchema),
  serverTime: z.string(),
});
export type MobileCampaignsResponse = z.infer<typeof mobileCampaignsResponseSchema>;

export const mobileEventSchema = z.object({
  type: z.enum(ADVERTISING_EVENT_TYPES),
  campaignId: publicIdSchema,
  beaconId: beaconIdentifierSchema,
  deviceToken: deviceTokenSchema,
  rssi: z.number().int().min(-127).max(20).nullish(),
  occurredAt: z.iso.datetime({ offset: true }).nullish(),
  platform: z.enum(MOBILE_PLATFORMS).nullish(),
  appVersion: z.string().trim().max(32).nullish(),
});
export type MobileEvent = z.infer<typeof mobileEventSchema>;

export const mobileEventsRequestSchema = z.object({
  events: z.array(mobileEventSchema).min(1).max(50),
});
export type MobileEventsRequest = z.infer<typeof mobileEventsRequestSchema>;

export const mobileEventsResponseSchema = z.object({
  accepted: z.number().int(),
  duplicates: z.number().int(),
  rejected: z.array(z.object({ index: z.number().int(), reason: z.string() })),
});
export type MobileEventsResponse = z.infer<typeof mobileEventsResponseSchema>;
